<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$adminPage='payments';$adminTitle='تراکنش‌های پرداخت';
$status=scalar_string($_GET['status']??'');$allowed=['created','requested','redirected','paid','failed','cancelled','reversed','partially_refunded','refunded'];if(!in_array($status,$allowed,true))$status='';
$gateway=scalar_string($_GET['gateway']??'');if(!in_array($gateway,['zibal','torobpay','snappay'],true))$gateway='';
$page=max(1,scalar_int($_GET['page']??1));$perPage=30;$where=' WHERE 1=1';$params=[];if($gateway!==''){$where.=' AND pt.gateway=?';$params[]=$gateway;}if($status!==''){$where.=' AND pt.status=?';$params[]=$status;}
$count=db()->prepare('SELECT COUNT(*) FROM payment_transactions pt'.$where);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$stmt=db()->prepare('SELECT pt.*,o.order_number,o.customer_name,o.phone FROM payment_transactions pt JOIN orders o ON o.id=pt.order_id'.$where.' ORDER BY pt.id DESC LIMIT '.$perPage.' OFFSET '.$offset);$stmt->execute($params);$rows=$stmt->fetchAll();
$labels=['created'=>'ایجادشده','requested'=>'در انتظار پرداخت','redirected'=>'ارسال به درگاه','paid'=>'موفق','failed'=>'ناموفق','cancelled'=>'لغوشده','reversed'=>'برگشت','partially_refunded'=>'بازپرداخت جزئی','refunded'=>'بازپرداخت کامل'];$gatewayLabels=['zibal'=>'زیبال','torobpay'=>'ترب‌پی','snappay'=>'اسنپ‌پی'];
require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><div><h1>تراکنش‌های پرداخت</h1><p class="muted"><?=fa_number($total)?> تراکنش</p></div><a class="btn btn-secondary" href="<?=e(app_url('admin/payment-settings.php'))?>">تنظیمات درگاه‌ها</a></div>
<form class="filters-admin"><select name="gateway"><option value="">همه درگاه‌ها</option><?php foreach($gatewayLabels as $key=>$label):?><option value="<?=$key?>" <?=$gateway===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><select name="status"><option value="">همه وضعیت‌ها</option><?php foreach($labels as $key=>$label):?><option value="<?=$key?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><button class="btn btn-secondary">فیلتر</button></form>
<div class="table-wrap"><table><thead><tr><th>درگاه</th><th>سفارش</th><th>مشتری</th><th>مبلغ</th><th>شناسه درگاه</th><th>مرجع</th><th>وضعیت</th><th>تاریخ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($gatewayLabels[$r['gateway']]??$r['gateway'])?></strong></td><td><a href="<?=e(app_url('admin/order.php?id='.(int)$r['order_id']))?>"><strong><?=e($r['order_number'])?></strong></a></td><td><?=e($r['customer_name'])?><br><small><?=e($r['phone'])?></small></td><td><?=fa_number(format_price((int)$r['amount']))?> تومان</td><td dir="ltr"><?=e($r['authority']??'-')?></td><td dir="ltr"><?=e($r['reference_id']??'-')?></td><td><span class="badge"><?=e($labels[$r['status']]??$r['status'])?></span></td><td><?=e(jalali_format($r['created_at']))?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8">تراکنشی پیدا نشد.</td></tr><?php endif?></tbody></table></div>
<?php if($pages>1):?><nav class="pagination"><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="<?=$i==$page?'active':''?>" href="?<?=e(http_build_query(['gateway'=>$gateway,'status'=>$status,'page'=>$i]))?>"><?=fa_number($i)?></a><?php endfor?></nav><?php endif?>
<?php require __DIR__.'/partials/footer.php';
